data.criteria:
{
  "urgent": "Reported evidence indicates a widespread failure or a blocked critical customer journey, such as checkout failing for every customer; other urgent evidence includes credible data loss or security impact. Missing diagnostic details alone do not reduce clearly established urgency.",
  "normal": "Reported evidence supports limited impact, a noncritical defect, or a viable workaround, with enough information to support routine prioritization. Do not select normal merely because severity clues are missing.",
  "needs_information": "The report lacks a concrete symptom or enough evidence to establish either urgent or normal impact, or contains unresolved contradictory impact claims. Select this option when details needed for prioritization are unknown; uncertainty about urgency is not evidence of normal impact. Clear widespread critical failures remain urgent despite missing diagnostics."
}
